let mapFocusLevel=null;
let screen='map',chapter=Math.ceil(session.p.Unlocked/100),selectedGem=null,gemHints=[],target=null,winShown=false,busy=false;
const menuJourney=new MenuJourney(action=>['events','lives','shop','settings','guide','journal','wheel','openDeal','share'].includes(action)||action.startsWith('preview:')||action.startsWith('lockedFeature:')||action==='ev:hub'||features.some(f=>action==='ev:'+f.id));
const gameAudio=new MeadowAudio(()=>session.p);
